import {blankProgress,mergeProgress} from './progress-core.mjs';
import {normalizeUsername,validUsername,validPassword,usernameEmail} from './identity.mjs';
const localKey=id=>'or-v3-progress:'+id;
export function readLocal(id='guest'){try{return mergeProgress(blankProgress(),JSON.parse(localStorage.getItem(localKey(id))))}catch{return blankProgress()}}
export function writeLocal(id,data){try{localStorage.setItem(localKey(id),JSON.stringify(data));return true}catch{return false}}
export class Account{
 constructor({onUser,onSync,onRemote}){Object.assign(this,{onUser,onSync,onRemote});this.user=null;this.config={};this.revision=0;this.serial=0;this.ready=false;this.saving=false;this.pending=null;this.retryCount=0}
 async init(){try{const response=await fetch('./account-config.json',{cache:'no-store'});this.config=await response.json();if(!this.config.url||!this.config.publishableKey)return;const {createClient}=await import('./vendor/supabase.mjs');this.client=createClient(this.config.url,this.config.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,flowType:'pkce'}});const {data,error}=await this.client.auth.getSession();if(error)throw error;this.ready=true;await this.acceptUser(data.session?.user||null);this.client.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY')window.dispatchEvent(new Event('or-password-recovery'));if(event==='SIGNED_IN'||event==='SIGNED_OUT'||event==='INITIAL_SESSION')setTimeout(()=>this.acceptUser(session?.user||null),0)})}catch(e){this.error=e.message;this.onSync?.('error')}}
 async acceptUser(user){if(user&&(!user.app_metadata?.organic_recall||!validUsername(user.user_metadata?.username))){await this.client.auth.signOut();user=null}if(this.user?.id===user?.id)return;this.serial++;this.retryCount=0;this.pending=null;clearTimeout(this.timer);this.user=user?{...user,username:normalizeUsername(user.user_metadata.username)}:null;this.revision=0;this.onUser?.(this.user,readLocal(user?.id));if(user)await this.load()}
 async load(){if(!this.user)return;const id=this.user.id,serial=this.serial;this.onSync?.('syncing');try{const {data,error}=await this.client.from('learning_state').select('data,revision').eq('user_id',id).maybeSingle();if(error)throw error;if(serial!==this.serial)return;this.revision=data?.revision||0;const merged=mergeProgress(readLocal(id),data?.data);writeLocal(id,merged);this.onRemote?.(merged);this.onSync?.('synced')}catch{if(serial===this.serial)this.onSync?.('error')}}
 queue(data){if(!this.user)return;this.retryCount=0;this.pending=data;clearTimeout(this.timer);this.timer=setTimeout(()=>this.flush(),800)}
 async flush(){if(!this.user||!this.pending||this.saving)return;this.saving=true;const data=this.pending;this.pending=null;const id=this.user.id,serial=this.serial;this.onSync?.('syncing');try{const {data:result,error}=await this.client.rpc('save_recall_state',{payload:data,expected_revision:this.revision,expected_user:id});if(error)throw error;if(serial!==this.serial)return;this.revision=result.revision;this.retryCount=0;if(result.conflict){const merged=mergeProgress(data,result.data);writeLocal(id,merged);this.onRemote?.(merged);this.pending=mergeProgress(merged,this.pending)}this.onSync?.('synced')}catch{if(serial===this.serial){this.pending=mergeProgress(data,this.pending);this.retryCount++;this.onSync?.('error')}}finally{this.saving=false;if(this.pending&&serial===this.serial&&navigator.onLine&&this.retryCount<3)this.timer=setTimeout(()=>this.flush(),this.retryCount?5000*this.retryCount:1400)}}
 requireClient(){if(!this.client)throw Error('backendPending')}
 async login(username,password){this.requireClient();if(!validUsername(username))throw Error('usernameInvalid');const {error}=await this.client.auth.signInWithPassword({email:await usernameEmail(username),password});if(error)throw error}
 async publicAction(action,username,password,recoveryCode){this.requireClient();if(!this.config.registrationReady)throw Error('backendPending');if(!validUsername(username))throw Error('usernameInvalid');if(!validPassword(password))throw Error('passwordInvalid');let result;try{const response=await fetch(this.config.url+'/functions/v1/username-auth',{method:'POST',headers:{apikey:this.config.publishableKey,'Content-Type':'application/json'},body:JSON.stringify({action,username:normalizeUsername(username),password,...(recoveryCode?{recoveryCode}:{})})});result=await response.json();if(!response.ok)throw Error(result.error||'accountUnavailable')}catch(error){if(error.message&&error.message!=='Failed to fetch')throw error;throw Error('accountUnavailable')}return result}
 async signup(username,password){return this.publicAction('register',username,password)}
 async reset(username,password,recoveryCode){return this.publicAction('recover',username,password,recoveryCode)}
 async logout(){this.requireClient();if(this.pending)await this.flush();const {error}=await this.client.auth.signOut();if(error)throw error;await this.acceptUser(null)}
}
